import time, statistics
from string_builders import N_PARTS as n

def acc(n=n):
    s = ""
    for i in range(n):
        s += f"part-{i},"
    return s

def jl(n=n):
    return "".join(f"part-{i}," for i in range(n))

def jllist(n=n):
    return "".join([f"part-{i}," for i in range(n)])

def acc_cell(n=n):
    # same '+=' accumulation, but s held in a cell (closure), which
    # defeats CPython's refcount-1 in-place concat fast path -> true O(n^2)
    s = ""
    def bump(p):
        nonlocal s
        s += p
    for i in range(n):
        bump(f"part-{i},")
    return s

import sys
print(sys.version)
for fn in (acc, jl, jllist):
    ts=[]
    for _ in range(5):
        t0=time.perf_counter(); fn(); ts.append(time.perf_counter()-t0)
    print(fn.__name__, [f"{t*1e3:.2f}" for t in ts], "median", f"{statistics.median(ts)*1e3:.3f} ms")
t0=time.perf_counter(); r=acc_cell(); dt=time.perf_counter()-t0
print("acc_cell one shot", f"{dt*1e3:.1f} ms")
